25	template<int s> class VNADatapoint {
26	public:
27		VNADatapoint() {
28			clear();
29		}
30	
31		void clear() {
32			num_values = 0;
33			pointNum = 0;
34			cdBm = 0;
35			frequency = 0;
36		}
37		bool addValue(float real, float imag, uint8_t stage, int sourceMask) {
38			if(num_values >= s) {
39				return false;
40			}
41			real_values[num_values] = real;
42			imag_values[num_values] = imag;
43			descr_values[num_values] = stage << DPNT_CONF_STAGE_OFFSET | sourceMask;
44			num_values++;
45			return true;
46		}
47	
48		bool encode(uint8_t *dest, uint16_t destSize) {
49			if(requiredBufferSize() > destSize) {
50				return false;
51			}
52			memcpy(dest, &frequency, DPNT_FREQ_LEN);
53			dest += DPNT_FREQ_LEN;
54			memcpy(dest, &cdBm, DPNT_POW_LVL_LEN);
55			dest += DPNT_POW_LVL_LEN;
56			memcpy(dest, &pointNum, DPNT_PNT_NUM_LEN);
57	        dest += DPNT_PNT_NUM_LEN;
58			memcpy(dest, real_values, num_values * DPNT_REAL_PART_LEN);
59			dest += num_values * DPNT_REAL_PART_LEN;
60			memcpy(dest, imag_values, num_values * DPNT_IMAG_PART_LEN);
61			dest += num_values * DPNT_IMAG_PART_LEN;
62			memcpy(dest, descr_values, num_values);
63			return true;
64		}
65	    void decode(const uint8_t *buffer, uint16_t size) {
66	        num_values = (size - (DPNT_FREQ_LEN + DPNT_POW_LVL_LEN + DPNT_PNT_NUM_LEN)) /
67	        		(DPNT_REAL_PART_LEN + DPNT_IMAG_PART_LEN + DPNT_DESC_LEN);
68	        memcpy(&frequency, buffer, DPNT_FREQ_LEN);
69	        buffer += DPNT_FREQ_LEN;
70	        memcpy(&cdBm, buffer, DPNT_POW_LVL_LEN);
71	        buffer += DPNT_POW_LVL_LEN;
72	        memcpy(&pointNum, buffer, DPNT_PNT_NUM_LEN);
73	        buffer += DPNT_PNT_NUM_LEN;
74	        memcpy(real_values, buffer, num_values * DPNT_REAL_PART_LEN);
75	        buffer += num_values * DPNT_REAL_PART_LEN;
76	        memcpy(imag_values, buffer, num_values * DPNT_IMAG_PART_LEN);
77	        buffer += num_values * DPNT_IMAG_PART_LEN;
78	        memcpy(descr_values, buffer, num_values);
79		}
80	
81		std::complex<double> getValue(uint8_t stage, uint8_t port, bool reference) {
82			uint8_t sourceMask = 0;
83			sourceMask |= 0x01 << port;
84			if(reference) {
85				sourceMask |= (int) Source::Reference;
86			}
87			for(int i=0;i<num_values;i++) {
88				if(descr_values[i] >> DPNT_CONF_STAGE_OFFSET != stage) {
89					continue;
90				}
91				if((descr_values[i] & sourceMask) != sourceMask) {
92					continue;
93				}
94				return std::complex<double>(real_values[i], imag_values[i]);
95			}
96			return std::numeric_limits<std::complex<double>>::quiet_NaN();
97		}
98	
99	    class Value {
100	    public:
101	        std::complex<double> value;
102	        uint8_t flags;
103	    };
104	    Value getValue(unsigned int index) {
105	        Value v;
106	        v.value = 0.0;
107	        v.flags = 0;
108	        if(index <= num_values) {
109	            v.value = std::complex<double>(real_values[index], imag_values[index]);
110	            v.flags = descr_values[index];
111	        }
112	        return v;
113	    }
114	    unsigned int getNumValues() {
115	        return num_values;
116	    }
117	
118		uint16_t requiredBufferSize() {
119			return DPNT_FREQ_LEN + DPNT_POW_LVL_LEN + DPNT_PNT_NUM_LEN +
120					num_values * (DPNT_REAL_PART_LEN + DPNT_IMAG_PART_LEN + DPNT_DESC_LEN);
121		}
122	
123		union {
124			uint64_t frequency;
125			uint64_t us;
126		};
127		int16_t cdBm;
128		uint16_t pointNum;
129	private:
130		float real_values[s];
131		float imag_values[s];
132		uint8_t descr_values[s];
133		uint8_t num_values;
134	};
