		} V1;
		struct {
	        int16_t portmin, portmax;
	        int16_t refmin, refmax;
	        float portreal, portimag;
	        float refreal, refimag;
	        uint8_t source_locked :1;
	        uint8_t LO_locked :1;
		} VFF;
        struct {
            int16_t portmin, portmax;
            int16_t refmin, refmax;
            float portreal, portimag;
            float refreal, refimag;
            uint8_t source_locked :1;
            uint8_t LO_locked :1;
            uint16_t temp_eCal; // in 1/100 °C
