17		int k;
18	
19		crc = ~crc;
20		while (len--) {
21			crc ^= *u8buf++;
22			for (k = 0; k < 8; k++)
23				crc = crc & 1 ? (crc >> 1) ^ CRC32_POLYGON : crc >> 1;
24		}
25		return ~crc;
