29	    if (!info || !len) {
30	        info->type = PacketType::None;
31			return 0;
32		}
33		uint8_t *data = buf;
34		/* Remove any out-of-order bytes in front of the frame */
35		while (*data != PCKT_HEADER_DATA) {
36			data++;
37			if(--len == 0) {
38				/* Reached end of data */
39				/* No frame contained in data */
40				info->type = PacketType::None;
41				return data - buf;
42			}
43		}
44		/* At this point, data points to the beginning of the frame */
45		if(len < PCKT_COMBINED_HEADER_LEN) {
46			/* the frame header has not been completely received */
47			info->type = PacketType::None;
48			return data - buf;
49		}
50	
51		/* Evaluate frame size */
52	    uint16_t length = data[PCKT_LENGTH_OFFSET] | ((uint16_t) data[2] << 8);
53	
54	    if(length > sizeof(PacketInfo) * 2 || length < PCKT_EXCL_PAYLOAD_LEN) {
55	        // larger than twice the maximum expected packet size or too small, probably an error, ignore
56	        info->type = PacketType::None;
57	        return 1;
58	    }
59	
60	    if(len < length) {
61			/* The frame payload has not been completely received */
62			info->type = PacketType::None;
63			return data - buf;
64		}
65	
66		/* The complete frame has been received, check checksum */
67		auto type = (PacketType) data[PCKT_TYPE_OFFSET];
68	    uint32_t crc = (uint32_t) data[length-4] | ((uint32_t) data[length-3] << 8) | ((uint32_t) data[length-2] << 16) | ((uint32_t) data[length-1] << 24);
69		if(type != PacketType::VNADatapoint) {
70			uint32_t compare = CRC32(0, data, length - PCKT_CRC_LEN);
71			if(crc != compare) {
72				// CRC mismatch, remove header
73				data += 1;
74				info->type = PacketType::None;
75				return data - buf;
76			}
77			// Valid packet, copy packet type and payload
78			memcpy(info, &data[PCKT_TYPE_OFFSET], length - 7);
79		} else {
