119	inline void App_Process() {
120		while(1) {
121			uint32_t notification;
122			if(xTaskNotifyWait(0x00, UINT32_MAX, &notification, 100) == pdPASS) {
123				// something happened
124				if(notification & FLAG_USB_PACKET) {
125					switch(recv_packet.type) {
126					case Protocol::PacketType::SweepSettings:
127						LOG_INFO("New settings received");
128						last_measure_packet = recv_packet;
129						sweepActive = VNA::Setup(recv_packet.settings);
130						Communication::SendWithoutPayload(Protocol::PacketType::Ack);
131						break;
132					case Protocol::PacketType::ManualControl:
133						sweepActive = false;
134						last_measure_packet = recv_packet;
135						Manual::Setup(recv_packet.manual);
136						Communication::SendWithoutPayload(Protocol::PacketType::Ack);
137						break;
138					case Protocol::PacketType::Reference:
139						HW::Ref::set(recv_packet.reference);
140						if(!sweepActive) {
141							// can update right now
142							HW::Ref::update();
143						}
144						Communication::SendWithoutPayload(Protocol::PacketType::Ack);
145						break;
146					case Protocol::PacketType::Generator:
147						sweepActive = true;
148						last_measure_packet = recv_packet;
149						LOG_INFO("Updating generator setting");
150						Generator::Setup(recv_packet.generator);
151						Communication::SendWithoutPayload(Protocol::PacketType::Ack);
152						break;
153					case Protocol::PacketType::SpectrumAnalyzerSettings:
154						sweepActive = true;
155						last_measure_packet = recv_packet;
156						LOG_INFO("Updating spectrum analyzer settings");
157						SA::Setup(recv_packet.spectrumSettings);
158						Communication::SendWithoutPayload(Protocol::PacketType::Ack);
159						break;
160					case Protocol::PacketType::RequestDeviceInfo: {
161						Communication::SendWithoutPayload(Protocol::PacketType::Ack);
162						Protocol::PacketInfo p;
163						p.type = Protocol::PacketType::DeviceInfo;
164						p.info = HW::Info;
165						Communication::Send(p);
166					}
167						break;
168					case Protocol::PacketType::RequestDeviceStatus: {
169						Communication::SendWithoutPayload(Protocol::PacketType::Ack);
170						Protocol::PacketInfo p;
171						p.type = Protocol::PacketType::DeviceStatus;
172						HW::getDeviceStatus(&p.status);
173						Communication::Send(p);
174					}
175						break;
176					case Protocol::PacketType::StopStatusUpdates: {
177						HW::setStatusUpdateFlag(false);
178						Communication::SendWithoutPayload(Protocol::PacketType::Ack);
179					}
180						break;
181					case Protocol::PacketType::StartStatusUpdates: {
182						HW::setStatusUpdateFlag(true);
183						Communication::SendWithoutPayload(Protocol::PacketType::Ack);
184					}
185						break;
186					case Protocol::PacketType::InitiateSweep: {
187						if(VNA::GetStandbyMode()) {
188							VNA::InitiateSweep();
189							Communication::SendWithoutPayload(Protocol::PacketType::Ack);
190						} else {
191							Communication::SendWithoutPayload(Protocol::PacketType::Nack);
192						}
193	
194					}
195						break;
196					case Protocol::PacketType::SetIdle:
197						HW::SetMode(HW::Mode::Idle);
198						sweepActive = false;
199						Communication::SendWithoutPayload(Protocol::PacketType::Ack);
200						break;
201			#ifdef HAS_FLASH
202					case Protocol::PacketType::ClearFlash:
203						HW::SetMode(HW::Mode::Idle);
204						sweepActive = false;
205						LOG_DEBUG("Erasing FLASH in preparation for firmware update...");
206						if(HWHAL::flash.eraseRange(0, Firmware::maxSize)) {
207							LOG_DEBUG("...FLASH erased")
208							Communication::SendWithoutPayload(Protocol::PacketType::Ack);
209						} else {
210							LOG_ERR("Failed to erase FLASH");
211							Communication::SendWithoutPayload(Protocol::PacketType::Nack);
212						}
213						break;
214					case Protocol::PacketType::FirmwarePacket:
215						LOG_INFO("Writing firmware packet at address %u", recv_packet.firmware.address);
216						if(HWHAL::flash.write(recv_packet.firmware.address, sizeof(recv_packet.firmware.data), recv_packet.firmware.data)) {
217							Communication::SendWithoutPayload(Protocol::PacketType::Ack);
218						} else {
219							LOG_ERR("Failed to write FLASH");
220							Communication::SendWithoutPayload(Protocol::PacketType::Nack);
221						}
222						break;
223					case Protocol::PacketType::PerformFirmwareUpdate: {
224						LOG_INFO("Firmware update process triggered");
225						auto fw_info = Firmware::GetFlashContentInfo();
226						if(fw_info.valid) {
227							Communication::SendWithoutPayload(Protocol::PacketType::Ack);
228							// Some delay to allow communication to finish
229							vTaskDelay(100);
230							Firmware::PerformUpdate(fw_info);
231							// should never get here
232							Communication::SendWithoutPayload(Protocol::PacketType::Nack);
233						}
234					}
235						break;
236			#endif
237					case Protocol::PacketType::RequestSourceCal:
238						Communication::SendWithoutPayload(Protocol::PacketType::Ack);
239						Cal::SendSource();
240						break;
241					case Protocol::PacketType::RequestReceiverCal:
242						Communication::SendWithoutPayload(Protocol::PacketType::Ack);
243						Cal::SendReceiver();
244						break;
245					case Protocol::PacketType::SourceCalPoint:
246						Cal::AddSourcePoint(recv_packet.amplitudePoint);
247						Communication::SendWithoutPayload(Protocol::PacketType::Ack);
248						break;
249					case Protocol::PacketType::ReceiverCalPoint:
250						Cal::AddReceiverPoint(recv_packet.amplitudePoint);
251						Communication::SendWithoutPayload(Protocol::PacketType::Ack);
252						break;
253					case Protocol::PacketType::RequestFrequencyCorrection:
254						Communication::SendWithoutPayload(Protocol::PacketType::Ack);
255						{
256							Protocol::PacketInfo send;
257							send.type = Protocol::PacketType::FrequencyCorrection;
258							send.frequencyCorrection.ppm = Cal::getFrequencyCal();
259							Communication::Send(send);
260						}
261						break;
262					case Protocol::PacketType::FrequencyCorrection:
263						Cal::setFrequencyCal(recv_packet.frequencyCorrection.ppm);
264						Communication::SendWithoutPayload(Protocol::PacketType::Ack);
265						break;
266					case Protocol::PacketType::RequestDeviceConfiguration:
267						Communication::SendWithoutPayload(Protocol::PacketType::Ack);
268						{
269							Protocol::PacketInfo send;
270							send.type = Protocol::PacketType::DeviceConfiguration;
271							send.deviceConfig = HW::getDeviceConfig();
272							Communication::Send(send);
273						}
274						break;
275					case Protocol::PacketType::DeviceConfiguration:
276						HW::setDeviceConfig(recv_packet.deviceConfig);
277						Communication::SendWithoutPayload(Protocol::PacketType::Ack);
278						break;
279					case Protocol::PacketType::ResetDeviceConfiguration:
280						HW::SetDefaultDeviceConfig();
281						Communication::SendWithoutPayload(Protocol::PacketType::Ack);
282						break;
283					case Protocol::PacketType::SetTrigger:
284						if(Trigger::GetMode() == Trigger::Mode::USB_GUI) {
285							Trigger::SetInput(true);
286							Communication::SendWithoutPayload(Protocol::PacketType::Ack);
287						} else {
288							Communication::SendWithoutPayload(Protocol::PacketType::Nack);
289						}
290						break;
291					case Protocol::PacketType::ClearTrigger:
292						if(Trigger::GetMode() == Trigger::Mode::USB_GUI) {
293							Trigger::SetInput(false);
294							Communication::SendWithoutPayload(Protocol::PacketType::Ack);
295						} else {
296							Communication::SendWithoutPayload(Protocol::PacketType::Nack);
297						}
298						break;
299					default:
300						// this packet type is not supported
301						Communication::SendWithoutPayload(Protocol::PacketType::Nack);
302						break;
303					}
304				}
305				if(notification & FLAG_TRIGGER_OUT_ISR) {
306					// trigger output (from FPGA) changed level
307					bool set = Trigger::GetOutput();
308					switch(Trigger::GetMode()) {
309					case Trigger::Mode::Off:
310						// nothing to do
311						break;
312					case Trigger::Mode::USB_GUI:
313						lastReportedTrigger = set;
314						Communication::SendWithoutPayload(set ? Protocol::PacketType::SetTrigger : Protocol::PacketType::ClearTrigger);
315						break;
316					case Trigger::Mode::ExtRef:
317						if(set) {
318							HWHAL::Si5351.Enable(HWHAL::SiChannel::ReferenceOut);
319						} else {
320							HWHAL::Si5351.Disable(HWHAL::SiChannel::ReferenceOut);
321						}
322						break;
323					case Trigger::Mode::Trigger:
324						// not supported by the hardware, nothing to do
325						break;
326					}
327				}
328			}
329			if(HW::TimedOut()) {
330				HW::SetMode(HW::Mode::Idle);
331				// insert the last received packet (restarts the timed out operation)
332				Communication::BlockNextAck();
333				USBPacketReceived(last_measure_packet);
334			}
335			HW::updateDeviceStatus();
336		}
337	}
