158		if(continous_length > usb_transmit_fifo_level) {
159			continous_length = usb_transmit_fifo_level;
160		}
161		if(continous_length > sizeof(usb_transmit_fifo)/ 2) {
162			continous_length = sizeof(usb_transmit_fifo) / 2;
163		}
164		hUsbDeviceFS.ep_in[EP_DATA_IN_ADDRESS & 0x7F].total_length = continous_length;
165		return USBD_LL_Transmit(&hUsbDeviceFS, EP_DATA_IN_ADDRESS, &usb_transmit_fifo[usb_transmit_read_index], continous_length) == USBD_OK;
