176	static uint8_t USBD_Class_DataIn(USBD_HandleTypeDef *pdev, uint8_t epnum) {
177		// A bulk transfer is complete when the endpoint does on of the following:
178		// - Has transferred exactly the amount of data expected
179		// - Transfers a packet with a payload size less than wMaxPacketSize or transfers a zero-length packet
180		if(epnum == (EP_DATA_IN_ADDRESS & 0x7F)) {
181			// transmission of fifo data, mark as empty
182			__disable_irq();
183			usb_transmit_fifo_level -= pdev->ep_in[epnum].total_length;
184			usb_transmit_read_index += pdev->ep_in[epnum].total_length;
185			usb_transmit_read_index %= sizeof(usb_transmit_fifo);
186			__enable_irq();
187		}
188		if (pdev->ep_in[epnum].total_length
189				&& !(pdev->ep_in[epnum].total_length % USB_FS_MAX_PACKET_SIZE)) {
190			pdev->ep_in[epnum].total_length = 0;
191			USBD_LL_Transmit(pdev, epnum, NULL, 0);
192		} else {
193			if(epnum == (EP_DATA_IN_ADDRESS & 0x7F)) {
194				if(usb_transmit_fifo_level > 0) {
195					trigger_next_fifo_transmission();
196				} else {
197					data_transmission_active = false;
198				}
199			} else {
200				log_transmission_active = false;
201			}
202		}
203		last_transmission = HAL_GetTick();
204		return USBD_OK;
