227		cb = receive_callback;
228		USBD_Init(&hUsbDeviceFS, &FS_Desc, 0);
229		USBD_RegisterClass(&hUsbDeviceFS, &USBD_ClassDriver);
230		USBD_Start(&hUsbDeviceFS);
231	    HAL_NVIC_SetPriority(USB_HP_IRQn, 0, 0);
232	    HAL_NVIC_EnableIRQ(USB_HP_IRQn);
233	    HAL_NVIC_SetPriority(USB_LP_IRQn, 5, 0);
234		HAL_NVIC_EnableIRQ(USB_LP_IRQn);
235	}
236	bool usb_transmit(const uint8_t *data, uint16_t length) {
237		if(!connection_okay()) {
238			// clear buffer and attempt to restart the transfer
239			data_transmission_active = false;
240			log_transmission_active = false;
241			usb_transmit_fifo_level = 0;
242		}
243		// attempt to add data to fifo
244		if(length > usb_available_buffer()) {
245			// data won't fit, abort
246			return false;
247		}
248		// grab pointer to write position
249		__disable_irq();
250		uint16_t write_index = usb_transmit_read_index + usb_transmit_fifo_level;
251		write_index %= sizeof(usb_transmit_fifo);
252		// copy the data to the fifo
253		uint16_t continous_length = sizeof(usb_transmit_fifo) - write_index;
254		if(continous_length > length) {
255			// can copy all data at once
256			memcpy(&usb_transmit_fifo[write_index], data, length);
257		} else {
258			// needs to copy two data segments
259			memcpy(&usb_transmit_fifo[write_index], data, continous_length);
260			memcpy(&usb_transmit_fifo[0], data + continous_length, length - continous_length);
261		}
262		// increment fifo level
263		usb_transmit_fifo_level += length;
264	
265		static bool first = true;
266		if(first) {
267			log_transmission_active = false;
268			first = false;
269		}
270		bool ret = true;
271		if(!data_transmission_active) {
272			last_transmission = HAL_GetTick();
273			ret = trigger_next_fifo_transmission();
274		}
275		__enable_irq();
276		return ret;
277	}
278	
279	void usb_log(const char *log, uint16_t length) {
280		if(!log_transmission_active) {
281			static uint8_t buffer[256];
282			memcpy(buffer, log, length);
283			hUsbDeviceFS.ep_in[EP_LOG_IN_ADDRESS & 0x7F].total_length = length;
284			if (USBD_LL_Transmit(&hUsbDeviceFS, EP_LOG_IN_ADDRESS, buffer, length) == USBD_OK) {
285			    log_transmission_active = true;
286			}
287		} else {
288			// still busy, unable to send log
289		}
290	}
291	
292	void USB_HP_IRQHandler(void)
293	{
294	  HAL_PCD_IRQHandler(&hpcd_USB_FS);
295	}
296	void USB_LP_IRQHandler(void)
297	{
298	  HAL_PCD_IRQHandler(&hpcd_USB_FS);
299	}
300	
301	uint16_t usb_available_buffer() {
302		return sizeof(usb_transmit_fifo) - usb_transmit_fifo_level;
303	}
304	
305	void usb_clear_buffer() {
306		usb_transmit_fifo_level = 0;
307		data_transmission_active = 0;
308	}
